import{_ as i}from"./chunks/verwaltung-einstellungen-vermerke.BM7Maf45.js";import{_ as a,o as s,c as l,a3 as r,j as e,a as n}from"./chunks/framework.z_KJ15Ep.js";const u="/bilder/grundlagen/s2zu-s3-quartalsnoten-aktivieren.png",d="/bilder/grundlagen/s2zu-s3-quartalsnoten-aktiviert.png",o="/bilder/grundlagen/s2zu-s3-auswahl-schuelerfilter.png",h="/bilder/grundlagen/gruppenprozesse-individualdaten-lernabschnitte.png",w=JSON.parse('{"title":"Von SchILD-NRW 2 auf SchILD-NRW 3 umsteigen","description":"","frontmatter":{"title":"Von SchILD-NRW 2 auf SchILD-NRW 3 umsteigen","source_pageid":1181,"source_revision":6944},"headers":[],"relativePath":"einstieg/grundlagen/wesentliche-unterschiede-zu-schild-nrw-2.md","filePath":"einstieg/grundlagen/wesentliche-unterschiede-zu-schild-nrw-2.md"}'),c={name:"einstieg/grundlagen/wesentliche-unterschiede-zu-schild-nrw-2.md"};function g(m,t,p,b,k,f){return s(),l("div",null,[...t[0]||(t[0]=[r('<h1 id="von-schild-nrw-2-auf-schild-nrw-3-umsteigen" tabindex="-1">Von SchILD-NRW 2 auf SchILD-NRW 3 umsteigen <a class="header-anchor" href="#von-schild-nrw-2-auf-schild-nrw-3-umsteigen" aria-label="Permalink to &quot;Von SchILD-NRW 2 auf SchILD-NRW 3 umsteigen&quot;">​</a></h1><p>Vergleichen Sie die technischen Grundlagen und Arbeitsabläufe beider Programmversionen. Beachten Sie insbesondere Datenbankzugriff, Ordnerstruktur und veränderte Eingabestellen.</p><p>SchILD-NRW 3 unterscheidet sich trotz des neues Aussehens in vielen Aspekten nicht bis kaum von den aus SchILD-NRW 2 gewohnten Abläufen.</p><p>In Bezug auf andere Aspekte kann es im Detail teils wichtige Unterschiede geben. Dieser Artikel soll nicht alle kleinen Änderungen auflisten, sondern auf einen schnellen Blick auf wichtige Veränderungen im Verhalten und Arbeitsablauf hinweisen.</p><p>Nehmen Sie auch die FAQ in dieser Dokumentation zur Kenntnis.</p><h2 id="technische-anderungen" tabindex="-1">Technische Änderungen <a class="header-anchor" href="#technische-anderungen" aria-label="Permalink to &quot;Technische Änderungen&quot;">​</a></h2><h3 id="datenbankserver-statt-ms-access-datenbank" tabindex="-1">Datenbankserver statt MS Access Datenbank <a class="header-anchor" href="#datenbankserver-statt-ms-access-datenbank" aria-label="Permalink to &quot;Datenbankserver statt MS Access Datenbank&quot;">​</a></h3><p>SchILD-NRW 3 nutzt einen Datenbankserver statt einer veralteten MS-Access-Datei. Damit ist es im Rahmen moderner Zugriffsbeschränkungen und Datensicherheit nicht mehr allen SchILD-Nutzern möglich, die Datenbank-Datei mit allen enthaltenen Daten (!) zu kopieren und selbst in andere Installationen zu bringen.</p><p>Nutzen Sie für interne Arbeitsbackups die Funktionen in <em>Verwaltung ➜ Datenbank</em>. Hier werden SchILD-Administrationsrechte benötigt.</p><p>Die großen Vorteile des Datenbankservers sind eine modernden Standards entsprechende Datensicherheit und Performance, letzteres gilt besonders im Mehrnutzer- und Netzwerkbetrieb.</p><p>Es wird in SchILD-NRW 3 exklusiv die Datenbank <em>MariaDB</em> unterstützt.</p><h3 id="nutzung-der-svws-datenbank" tabindex="-1">Nutzung der SVWS-Datenbank <a class="header-anchor" href="#nutzung-der-svws-datenbank" aria-label="Permalink to &quot;Nutzung der SVWS-Datenbank&quot;">​</a></h3><p>Hierbei ist zu beachten, dass SchILD-NRW-3 selbst nur noch ein Clientprogramm ist und nicht mehr die eigene Datenbankverwaltung mitbringt, sondern die SVWS-Datenbank mit nutzt.</p><h3 id="schild-nrw-und-der-svws-server" tabindex="-1">SchILD-NRW und der SVWS-Server <a class="header-anchor" href="#schild-nrw-und-der-svws-server" aria-label="Permalink to &quot;SchILD-NRW und der SVWS-Server&quot;">​</a></h3><p>Zusätzlich zu SchILD-NRW sind auch Updates zum SVWS-Server zu installieren. SchILD-NRW benötigt den aktuellen, zur verwendeten Version passenden SVWS-Server.</p><h3 id="ordnerstrukturen" tabindex="-1">Ordnerstrukturen <a class="header-anchor" href="#ordnerstrukturen" aria-label="Permalink to &quot;Ordnerstrukturen&quot;">​</a></h3><p>Für SchILD-NRW 3 und den SVWS-Server gibt es vier Ordner:</p><ul><li>Im <strong>Installationsordner von SchILD-NRW 3</strong> haben Nutzer selbst nur Leserechte. SchILD-NRW-3 kann nur gestartet werden. Hier liegen keinerlei Nutzerdaten.</li><li>Im <strong>Installationsordner des SVWS-Servers</strong> und im <strong>Ordner mit den Daten des SVWS-Servers</strong> haben Nutzer keinerlei Rechte und sie sehen diese gar nicht.</li><li>Alle Nutzerdaten und Daten zur Arbeit mit SchILD-NRW 3 und dem SVWS-Server liegen im <strong>SVWS-Arbeitsverzeichnis</strong>.</li></ul><h3 id="arbeitssicherungen-in-schild-nrw-verwalten" tabindex="-1">Arbeitssicherungen in SchILD-NRW verwalten <a class="header-anchor" href="#arbeitssicherungen-in-schild-nrw-verwalten" aria-label="Permalink to &quot;Arbeitssicherungen in SchILD-NRW verwalten&quot;">​</a></h3><p>Im Gegensatz zu bisherigen Datenbank-Lösungen lassen sich Backups - entsprechende Berechtigungen des Nutzers vorausgesetzt - nun von SchILD-NRW aus erzeugen und wieder einlesen.</p><p>Die Backups lassen sich auch in anderen SchILD-NRW-Installationen einlesen.</p>',21),e("div",{"data-hint-kind":"info",class:"info custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"info","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("circle",{cx:"12",cy:"12",r:"9"}),e("path",{d:"M12 11v6m0-10v.1"})]),n("Hinweis")]),e("p",null,"Technisch gesehen handelt es sich hierbei um Datenbank-Migrationen.")],-1),e("h3",{id:"kein-master-zugang",tabindex:"-1"},[n("Kein Master-Zugang "),e("a",{class:"header-anchor",href:"#kein-master-zugang","aria-label":'Permalink to "Kein Master-Zugang"'},"​")],-1),e("p",null,'Es gibt in SchILD-NRW 3 keinen Master-Zugang, eine sogenannte "Backdoor", zu Datenbanken oder zu SchILD-NRW. Dieses Konzept ist nicht mehr zeitgemäß.',-1),e("div",{"data-hint-kind":"important",class:"warning custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"important","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("circle",{cx:"12",cy:"12",r:"9"}),e("path",{d:"M12 7v6m0 4v.1"})]),n("Wichtig")]),e("p",null,"Achten Sie daher bitte auf Ihre Kennwörter. Nehmen Sie hierzu den Bereich zu den Nutzerarten in den FAQ zur Kenntnis.")],-1),r('<h3 id="klare-trennung-der-ordner" tabindex="-1">Klare Trennung der Ordner <a class="header-anchor" href="#klare-trennung-der-ordner" aria-label="Permalink to &quot;Klare Trennung der Ordner&quot;">​</a></h3><p>Im SchILD-NRW3-Installationsverzeichnis ist keinerlei Nutzertätigkeit mehr vorgesehen. In diesem Verzeichnis schreibt einzig der SchILD-Installer. Nutzer benötigen nur Lesezugriff, um SchILD-NRW3 starten zu können.</p><p>Alle Nutzerdaten für SchILD-NRW - Reporting, Im- und Export usw. - liegen im <em>SVWS-Arbeitsverzeichnis</em>.</p><p>Auf die beiden Verzeichnisse des SVWS-Servers, einmal das Installationsverzeichnis und dann das Datenverzeichnis, haben Nutzer keinerlei Zugriff.</p><h3 id="keine-pop-up-und-schwebenden-fenster" tabindex="-1">Keine Pop Up- und schwebenden Fenster <a class="header-anchor" href="#keine-pop-up-und-schwebenden-fenster" aria-label="Permalink to &quot;Keine Pop Up- und schwebenden Fenster&quot;">​</a></h3><p>In SchILD-NRW 3 wurde darauf verzichtet, Pop-Up-Fenster und schwebende Fenster zur Eingabe zu verwenden.</p><h3 id="json-dateiformat" tabindex="-1">JSON-Dateiformat <a class="header-anchor" href="#json-dateiformat" aria-label="Permalink to &quot;JSON-Dateiformat&quot;">​</a></h3><p>Für den strukturierten Datenaustausch wird an verschiedenen Stellen das JSON-Dateiformat eingesetzt.</p><p>Konsultieren Sie hierzu auch die kurze Einführung zu diesen Format unter den Tutorials.</p><h3 id="speicherort-der-asdtabs-mdb-und-schulver-mdb" tabindex="-1">Speicherort der ASDTABS.MDB und schulver.mdb <a class="header-anchor" href="#speicherort-der-asdtabs-mdb-und-schulver-mdb" aria-label="Permalink to &quot;Speicherort der ASDTABS.MDB und schulver.mdb&quot;">​</a></h3><p>Für technisch versierte Nutzer: Die Dateien ASDTABS.mdb und schulver.mdb zur Statistik ist nun nicht mehr im Unterordner <em>\\keytabs\\</em> gespeichert, sondern in <em>\\IT-NRW\\</em>.</p><p>Entsprechend gibt es das Verzeichnis <em>\\LDS\\</em> nicht mehr, da die Statistik nicht über ein <em>&quot;Landesamt für Datenverarbeitung und Statistik&quot;</em>, sondern über IT-NRW läuft.</p><h3 id="reports-in-schild-nrw-3-und-schild-nrw-2" tabindex="-1">Reports in SchILD-NRW 3 und SchILD-NRW 2 <a class="header-anchor" href="#reports-in-schild-nrw-3-und-schild-nrw-2" aria-label="Permalink to &quot;Reports in SchILD-NRW 3 und SchILD-NRW 2&quot;">​</a></h3><p>Beim Öffnen von hochgradig individuell gestaltenten SchILD-NRW 2-Reports kann es zu Problemen mit SchILD-NRW3 führen. Dies gilt besonders, wenn eigene Datenquellen definiert wurden.</p><p>Grundsätzlich sind die Reports von SchILD-NRW 2 mit SchILD-NRW3 kompatibel und können verwendet werden.</p>',15),e("div",{"data-hint-kind":"caution",class:"danger custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"caution","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("path",{d:"m10.3 4-8 14A2 2 0 0 0 4 21h16a2 2 0 0 0 1.7-3l-8-14a2 2 0 0 0-3.4 0Z"}),e("path",{d:"M12 9v4m0 4v.1"})]),n("Achtung")]),e("p",null,[e("strong",null,"Kompatibilität von SchILD-NRW 2 und SchILD-NRW 3:")]),e("ol",null,[e("li",null,"Reports aus SchILD-NRW 2 können grundsätzlich weiterverwendet werden. Falls ein Report in SchILD-NRW 3 nicht richtig funktioniert, öffnen Sie ihn dort im Reportdesigner und speichern Sie ihn ohne weitere Änderungen. Dabei wird das Dateiformat an die neuere Version des Reportdesigners angepasst."),e("li",null,"Obwohl die Reports grundsätzlich kompatibel sind, gibt es viele SchILD2-Reports in denen über die letzten Jahrzehnte auf mitunter sehr kreative Weise gebastelt wurde. Hier können durchaus Fehler auftreten."),e("li",null,"Einige veraltete Komponenten aus dem SchILD2-Report-Baukausten sind in SchILD3 nicht mehr vorhanden: Dies bezieht sich hauptsächlich auf die Grid-Komponenten, auch die alten Kreuztabellen existieren so nicht mehr in den neuen Versionen des Reportbaukastens. Reports, die diese nutzen, werden nicht mehr funktionieren. Die Funktionalitäten der alten sind in SchILD3 weiterhin über andere Wege - leichter - umsetzen."),e("li",null,"Beachten Sie hier den folgenden Tipp.")])],-1),e("div",{"data-hint-kind":"tip",class:"tip custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"tip","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("path",{d:"M9 18h6m-5 3h4m-5-6c-4-3-4-9 0-11 5-3 11 1 9 6-.5 2-2 3-3 5v1H9z"})]),n("Tipp")]),e("p",null,"Für SchILD-NRW 3 wurden die Basisreportsammlung und die schulformspezifischen Reports überarbeitet. Prüfen Sie bei der Umstellung, welche vorhandenen Reports durch die neuen Vorlagen ersetzt werden können. So können Sie einheitlich gestaltete Reports nutzen und gegebenenfalls Ihre Arbeitsabläufe vereinfachen."),e("p",null,"Beachten Sie bei neuen Downloads der Basisreportsammlung, dass mittlerweile eine Version für SchILD-NRW-3 angeboten wird.")],-1),r('<h3 id="datenquellen-im-reporting" tabindex="-1">Datenquellen im Reporting <a class="header-anchor" href="#datenquellen-im-reporting" aria-label="Permalink to &quot;Datenquellen im Reporting&quot;">​</a></h3><p>Grundsätzlich funktionieren die Datenquellen im Reporting wie in SchILD-NRW-2. Es gibt unter Umständen an einigen Stellen leichte Neuerungen, zum Beispiele neue Felder in Datenquelle <em>SchildUmgebung</em> für verschiedene Formate von Schuljahr/Abschnitt.</p><h3 id="statistikrelevante-felder-individuell-hervorheben" tabindex="-1">Statistikrelevante Felder individuell hervorheben <a class="header-anchor" href="#statistikrelevante-felder-individuell-hervorheben" aria-label="Permalink to &quot;Statistikrelevante Felder individuell hervorheben&quot;">​</a></h3><p>Statistikrelevante Felder sind mit einem Sternchen * gekennzeichnet. Es ist per Standard keine Farbe für diese Felder mehr gesetzt.</p><p>Jedem Nutzer sei es empfohlen, direkt beim Beginn der Arbeit mit SchILD-NRW-3 eine Standardfarbe für <strong>Statistikrelevante Felder</strong> zu setzen. Tun Sie dies über <strong>Verwaltung ➜ Einstellungen ➜ Farbe für statistikrelevante Felder</strong>.</p><h2 id="anderungen-im-workflow" tabindex="-1">Änderungen im Workflow <a class="header-anchor" href="#anderungen-im-workflow" aria-label="Permalink to &quot;Änderungen im Workflow&quot;">​</a></h2><h3 id="daten-zum-aktuellen-halbjahr" tabindex="-1">Daten zum Aktuellen Halbjahr <a class="header-anchor" href="#daten-zum-aktuellen-halbjahr" aria-label="Permalink to &quot;Daten zum Aktuellen Halbjahr&quot;">​</a></h3><p>Die Daten zum aktuellen Halbjahr der Schüler werden nicht mehr doppelt im <em>aktuellen Halbjahr</em> (Lernabschnitt) und in den <em>Individualdaten I</em> gespeichert, sondern nur noch im aktuellen Halbjahr.</p>',8),e("div",{"data-hint-kind":"caution",class:"danger custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"caution","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("path",{d:"m10.3 4-8 14A2 2 0 0 0 4 21h16a2 2 0 0 0 1.7-3l-8-14a2 2 0 0 0-3.4 0Z"}),e("path",{d:"M12 9v4m0 4v.1"})]),n("Achtung")]),e("p",null,"Wenn also das aktuelle Halbjahr bei einem Schüler gelöscht wird, sind die aktuellen Informationen zu Klasse, Jahrgang, Prüfungsordnung usw. beim Schüler nicht mehr vorhanden und müssen anderweitig neu eingetragen beziehungsweise wiederhergestellt werden.")],-1),r('<p>Entsprechend sind die Anzeigen in den Individualdaten I und II der Daten zu Förderschwerpunkt oder Merkmalen und so weiter im Nur-Lesemodus zur Ansicht.</p><h3 id="klassen-werden-fur-lernabschnitte-angelegt" tabindex="-1">Klassen werden für Lernabschnitte angelegt <a class="header-anchor" href="#klassen-werden-fur-lernabschnitte-angelegt" aria-label="Permalink to &quot;Klassen werden für Lernabschnitte angelegt&quot;">​</a></h3><p>Im Katalog &quot;Klassen- und Versetzungstabelle&quot; werden die Klassen für jeden Lernabschnitt angelegt. Der Schalter &quot;sichtbar&quot; und dann das Filtern auf &quot;nur sichtbare Klassen&quot; entfällt somit. Im Kopf der Klassenliste wird nun der jeweilige Lernabschnitt gewählt.</p><p>Weiterhin lassen sich Klassenleitungen für die Lernabschnitte setzen und damit auch archivieren.</p><h3 id="klassenleitungen-gemeinsam-zuordnen" tabindex="-1">Klassenleitungen gemeinsam zuordnen <a class="header-anchor" href="#klassenleitungen-gemeinsam-zuordnen" aria-label="Permalink to &quot;Klassenleitungen gemeinsam zuordnen&quot;">​</a></h3><p>Statt einen Klassenlehrkraft und eine stellvertretende Lehrkraft zu setzen, kann nun eine Liste mit Lehrkräften als Klassenleitung angelegt werden.</p><p>Somit findet keine auf diesen beiden Rollen basierende Hierarchisierung mehr statt und es können mehr als zwei Personen erfasst werden.</p><h3 id="geanderte-erfassung-der-quartale" tabindex="-1">Geänderte Erfassung der <em>Quartale</em> <a class="header-anchor" href="#geanderte-erfassung-der-quartale" aria-label="Permalink to &quot;Geänderte Erfassung der *Quartale*&quot;">​</a></h3><p><a href="/bilder/grundlagen/s2zu-s3-quartalsnoten-aktivieren.png"><img src="'+u+'" alt="Verwaltung ➜ Einstellungen ➜ Globale Einstellungen ➜ Ansicht: Aktivieren Sie Verwendung von Quartalsnoten in den Leistungsdaten der Schüler." loading="lazy"></a></p><p><em>Verwaltung ➜ Einstellungen ➜ Globale Einstellungen ➜ Ansicht: Aktivieren Sie Verwendung von Quartalsnoten in den Leistungsdaten der Schüler.</em></p><p><em>Quartale als Lernabschnitte</em> werden nicht mehr unterstützt.</p><p>Die Halbjahre - und ihre Abkürzungen - können nach wie vor in &quot;Semester&quot;, &quot;Abschnitt&quot;, &quot;Halbjahr&quot; oder eine freie Bezeichnung umbenannt werden.</p><p>Entsprechend sind nur für Quartale relevante Funktionen aus dem Reporting entfernt worden.</p><p><a href="/bilder/grundlagen/s2zu-s3-quartalsnoten-aktiviert.png"><img src="'+d+'" alt="Die Quartalsnoten stehen nun über Schüler ➜ Akt. Halbjahr ➜ Leistungsdaten als weitere Spalte zur Verfügung." loading="lazy"></a></p><p><em>Die Quartalsnoten stehen nun über Schüler ➜ Akt. Halbjahr ➜ Leistungsdaten als weitere Spalte zur Verfügung.</em></p><p>Sie können unter <em>Verwaltung ➜ Einstellungen ➜ Globale Einstellungen</em> im Bereich <em>Ansicht</em> den Haken bei <strong>Quartalsnoten zeigen</strong> setzen.</p><p>Dann wird in den Schüler-Leistungsdaten des <em>Aktuellen Lernabschnitts</em> einen weitere Spalte für <em>Quartalsnoten</em> anzeigt.</p>',17),e("div",{"data-hint-kind":"tip",class:"tip custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"tip","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("path",{d:"M9 18h6m-5 3h4m-5-6c-4-3-4-9 0-11 5-3 11 1 9 6-.5 2-2 3-3 5v1H9z"})]),n("Tipp")]),e("p",null,[n("Nutzen Sie alternativ oder zusätzlich "),e("em",null,"Teilleistungen"),n(", um Elternsprechtagsnoten, Aufschlüssellungen in mündlich/schriftlich usw. zu erfassen.")])],-1),e("div",{"data-hint-kind":"info",class:"info custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"info","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("circle",{cx:"12",cy:"12",r:"9"}),e("path",{d:"M12 11v6m0-10v.1"})]),n("Hinweis")]),e("p",null,"Bei der Migration einer Schule im Quartalsbetrieb werden die Noten der Quartale automatisch in die Spalte des zugehörigen Halbjahres eingetragen."),e("p",null,"Die Migration einer Datenbank mit Quartalen dauert einige (!) Zeit länger als eine normale Migration.")],-1),r('<h3 id="ergebnisse-der-versetzungs-und-abschlussberechnungen" tabindex="-1">Ergebnisse der Versetzungs- und Abschlussberechnungen <a class="header-anchor" href="#ergebnisse-der-versetzungs-und-abschlussberechnungen" aria-label="Permalink to &quot;Ergebnisse der Versetzungs- und Abschlussberechnungen&quot;">​</a></h3><p>Die Ergebnisse der Versetzungs- und Abschlussberechnungen werden für jeden Lernabschnitt getrennt gespeichert.</p><p>Damit ist auch die erneute Berechnung für vorherige Lernabschnitte möglich.</p><h3 id="facher-der-oberstufe-im-svws-webclient" tabindex="-1">Fächer der Oberstufe im SVWS-Webclient <a class="header-anchor" href="#facher-der-oberstufe-im-svws-webclient" aria-label="Permalink to &quot;Fächer der Oberstufe im SVWS-Webclient&quot;">​</a></h3><p>Die <strong>Fächer der Oberstufe</strong> werden nun über den SVWS-Webclient verwaltet. Nutzen Sie hier die Dokumentation des SVWS-Webclients <a href="https://doku.svws-nrw.de" target="_blank" rel="noreferrer">[1]</a>.</p><h3 id="nur-noch-eine-erfassung-der-zuwanderungsgeschichte" tabindex="-1">Nur noch eine Erfassung der Zuwanderungsgeschichte <a class="header-anchor" href="#nur-noch-eine-erfassung-der-zuwanderungsgeschichte" aria-label="Permalink to &quot;Nur noch eine Erfassung der Zuwanderungsgeschichte&quot;">​</a></h3><p>Die <strong>Vereinfachte Erfassung der Zuwanderungsgeschichte</strong> wird vom neuen Datenbankserver nicht mehr unterstützt und damit bietet sich nur noch eine Option zur Erfassung der Zuwanderungsgeschichte.</p><p>Bei der Statistik wird bei einem &quot;nicht deutschen&quot; Eintrag korrekt &quot;Nicht deutsch&quot; gemeldet, die übrige Zuwanderungsgeschichte wäre zukünftig einzupflegen.</p><h3 id="erzieherfunktionen-sind-uber-personengruppen-zu-erfassen" tabindex="-1">Erzieherfunktionen&quot; sind über &quot;Personengruppen&quot; zu erfassen <a class="header-anchor" href="#erzieherfunktionen-sind-uber-personengruppen-zu-erfassen" aria-label="Permalink to &quot;Erzieherfunktionen&quot; sind über &quot;Personengruppen&quot; zu erfassen&quot;">​</a></h3><p>Die Erzieherfunktionen, die unter <em>Schüler ➜ Erziehungsberechtigte</em> gesetzt wurden, fallen weg, um das Management der unterschiedlichsten Gruppen zu vereinheitlichen.</p><p>Nutzen Sie für diese bisherige Funktion die <strong>Personengruppen</strong>, die sich über das Menü <strong>Kataloge ➜ Personengruppen</strong> verwalten lassen.</p><h3 id="wegfall-des-filter-ii-und-neue-bezeichnung-schulerfilter" tabindex="-1">Wegfall des Filter II und neue Bezeichnung <em>&quot;Schülerfilter&quot;</em> <a class="header-anchor" href="#wegfall-des-filter-ii-und-neue-bezeichnung-schulerfilter" aria-label="Permalink to &quot;Wegfall des Filter II und neue Bezeichnung *&quot;Schülerfilter&quot;*&quot;">​</a></h3><p><a href="/bilder/grundlagen/s2zu-s3-auswahl-schuelerfilter.png"><img src="'+o+'" alt="Der Filter I heißt jetzt Schülerfilter." loading="lazy"></a></p><p><em>Der Filter I heißt jetzt Schülerfilter.</em></p><p>Der alte <em>&quot;Filter I&quot;</em> heißt nun <em>&quot;Schülerfilter&quot;</em>, funktioniert von der Umbenennung abgesehen aber identisch.</p><p>Der <em>Filter II</em> ist in SchILD-NRW 3 nicht mehr enthalten.</p><h3 id="serienbriefdruck-mit-ms-word-uber-export" tabindex="-1">Serienbriefdruck mit MS Word über Export <a class="header-anchor" href="#serienbriefdruck-mit-ms-word-uber-export" aria-label="Permalink to &quot;Serienbriefdruck mit MS Word über Export&quot;">​</a></h3><p>Der Druck von Serienbriefen über MS Word wird nicht mehr über eine Druckausgabe angestoßen, sondern wird über <em>Verwaltung ➜ Export</em> ➜ <strong>Datenexport im xlsx- oder txt-Format</strong> durch Aktivieren des Hakens <strong>Nach dem Export Word-Seriendruck starten</strong> angestoßen.</p><p>Wurde keine eigene Steuerdatei definiert und diese leer gelassen, stehen die zum Export gewählten Felder als Word-Serienbriefdruck-Felder zur Verfügung.</p>',19),e("div",{"data-hint-kind":"info",class:"info custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"info","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("circle",{cx:"12",cy:"12",r:"9"}),e("path",{d:"M12 11v6m0-10v.1"})]),n("Hinweis")]),e("p",null,[n("Nehmen Sie an dieser Stelle bitte unbedingt die komplett überarbeiteten "),e("strong",null,"Basisreports"),n(" und die neue "),e("strong",null,"Serienbriefsammlung"),n(" zur Kenntnis! Arbeiten Sie so viel wie möglich mit den neuen Standardreports.")])],-1),e("h3",{id:"neuer-gruppenprozess-alle-vornamen-anpassen",tabindex:"-1"},[n('Neuer Gruppenprozess "Alle Vornamen anpassen" '),e("a",{class:"header-anchor",href:"#neuer-gruppenprozess-alle-vornamen-anpassen","aria-label":'Permalink to "Neuer Gruppenprozess "Alle Vornamen anpassen""'},"​")],-1),e("p",null,'Durch den Gruppenprozess Alle Vornamen anpassen kann eine Korrektur für den Feldeintrag "Alle Vornamen" vorgenommen werden.',-1),e("p",null,'Durch diesen Prozess wird der Rufname in das Feld "Alle Vornamen" übertragen, sofern das Feld "Alle Vornamen" nicht leer ist und der Rufname dort noch nicht vorhanden ist.',-1),e("div",{"data-hint-kind":"info",class:"info custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"info","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("circle",{cx:"12",cy:"12",r:"9"}),e("path",{d:"M12 11v6m0-10v.1"})]),n("Hinweis")]),e("p",null,"Dieser ist besonders vor einer Migration interessant.")],-1),r('<p><a href="/bilder/grundlagen/gruppenprozesse-individualdaten-lernabschnitte.png"><img src="'+h+'" alt="Bearbeiten eines Lernabschnitt, inklusive der Versetzungsvermerke über Gruppenprozesse ➜ Individualdaten ändern." loading="lazy"></a></p><p><em>Bearbeiten eines Lernabschnitt, inklusive der Versetzungsvermerke über Gruppenprozesse ➜ <strong>Individualdaten ändern</strong>.</em></p><h3 id="gruppenprozess-lernabschnitte-individuell-anlegen-bearbeite-fallt-weg" tabindex="-1">Gruppenprozess &quot;Lernabschnitte individuell anlegen/bearbeite&quot; fällt weg <a class="header-anchor" href="#gruppenprozess-lernabschnitte-individuell-anlegen-bearbeite-fallt-weg" aria-label="Permalink to &quot;Gruppenprozess &quot;Lernabschnitte individuell anlegen/bearbeite&quot; fällt weg&quot;">​</a></h3><p>Der Gruppenprozess Lernabschnitte individuell anlegen/bearbeiten wird in SchILD-NRW3 nicht mehr benötigt.</p><p><em>Lernabschnitte</em>, also die Kombination aus <em>Schuljahr und Halbjahr</em> werden nun über die Individualdaten erfasst können damit über <em>Gruppenprozesse ➜ Individualdaten ändern</em> im Reiter <em>Lernabschnitte</em> bearbeitet werden. Wählen Sie das passende Schuljahr/Halbjahr über das Feld <strong>Schuljahr</strong>.</p><p>Damit ist der erste genannte Gruppenprozess nicht mehr notwendig.</p><h3 id="gruppenprozess-versetzungsvermerk-andern-fallt-weg" tabindex="-1">Gruppenprozess &quot;Versetzungsvermerk ändern&quot; fällt weg <a class="header-anchor" href="#gruppenprozess-versetzungsvermerk-andern-fallt-weg" aria-label="Permalink to &quot;Gruppenprozess &quot;Versetzungsvermerk ändern&quot; fällt weg&quot;">​</a></h3><p>Der <em>Versetzungsvermerk</em> wird nun ebenfalls über den Reiter <em>Lernabschnitte</em> in <em>Gruppenprozesse ➜ Individualdaten ändern</em> verwaltet. Wählen Sie das passende <strong>Schuljahr</strong> für den korrekten Lernabschnitt und nutzen Sie dann das Feld <strong>Vers.-Vermerk</strong>.</p><p>Ein gesonderter Gruppenprozess ist damit nicht notwendig.</p><h3 id="gruppenprozess-lernabschnitte-mit-standardangaben-anlegen-fallt-weg" tabindex="-1">Gruppenprozess &quot;Lernabschnitte mit Standardangaben anlegen&quot; fällt weg <a class="header-anchor" href="#gruppenprozess-lernabschnitte-mit-standardangaben-anlegen-fallt-weg" aria-label="Permalink to &quot;Gruppenprozess &quot;Lernabschnitte mit Standardangaben anlegen&quot; fällt weg&quot;">​</a></h3><p>Wenn in SchILD-NRW 3 ein Schüler aufgenommen wird, ist automatisch ein Lernabschnitt mit dem Abschnitt, in den die Aufnahme erfolgt, angelegt worden. Damit fällt auch dieser Gruppenprozess weg.</p><h3 id="gruppenprozesse-kurse-zuweisen-werden-zusammengefasst" tabindex="-1">Gruppenprozesse &quot;Kurse zuweisen&quot; werden zusammengefasst <a class="header-anchor" href="#gruppenprozesse-kurse-zuweisen-werden-zusammengefasst" aria-label="Permalink to &quot;Gruppenprozesse &quot;Kurse zuweisen&quot; werden zusammengefasst&quot;">​</a></h3><p>Statt der zwei getrennten Gruppenprozesse <em>Kurse zuweisen (Einzel)</em> und <em>Kurse zuweisen (Mehrere)</em> gibt es in SchILD-NRW3 nur einen <em>Kurse zuweisen</em> benannten Gruppenprozess. Der Einzelprozess wurde entfernt, da sich mit dem tabellarischen Verfahren auch nur ein einzelner Kurs zuweisen lässt.</p><h3 id="vermerke-haben-einen-eigenen-reiter" tabindex="-1">Vermerke haben einen eigenen Reiter <a class="header-anchor" href="#vermerke-haben-einen-eigenen-reiter" aria-label="Permalink to &quot;Vermerke haben einen eigenen Reiter&quot;">​</a></h3><p><a href="/bilder/schueler/verwaltung-einstellungen-vermerke.png"><img src="'+i+'" alt="Aktivieren und Deaktivieren Sie den Reiter Vermerke über die Einstellungen." loading="lazy"></a></p><p><em>Aktivieren und Deaktivieren Sie den Reiter Vermerke über die Einstellungen.</em></p><p>Die Vermerke finden sich nicht mehr bei <em>Schüler ➜ Laufbahninfo</em>, sondern haben einen eigenen Reiter <em>Schüler ➜ Vermerke</em>.</p><p>Dieser Reiter kann nun in den Einstellungen deaktiviert werden, falls Ihre Schule keine Vermerke verwenden möchte.</p><p>Sie finden den Haken für <strong>Karteireiter &quot;Vermerke&quot; zeigen</strong> zur Steuerung unter <em>Verwaltung ➜ Einstellungen ➜ Globale Einstellungen ➜ Allgemeines ➜ Ansicht</em>.</p><h3 id="bemerkungen-sind-nun-ein-vermerk" tabindex="-1">Bemerkungen sind nun ein Vermerk <a class="header-anchor" href="#bemerkungen-sind-nun-ein-vermerk" aria-label="Permalink to &quot;Bemerkungen sind nun ein Vermerk&quot;">​</a></h3><p>Das Feld <strong>Bemerkungen</strong> in den <em>Individualdaten I</em> wurde entfernt.</p><p>Werden bei der Migration der Datenbank Bemerkungen in den Individualdaten gefunden, werden diese als ein <em>Vermerk Bemerkungen</em> abgelegt.</p><h3 id="sportbefreiungen-werden-ein-vermerk" tabindex="-1">Sportbefreiungen werden ein Vermerk <a class="header-anchor" href="#sportbefreiungen-werden-ein-vermerk" aria-label="Permalink to &quot;Sportbefreiungen werden ein Vermerk&quot;">​</a></h3><p>Die <em>Sportbefreiungen</em> aus den <em>Individualdaten I</em> gibt es in dieser Form in SchILD-NRW 3 nicht mehr. Existierende Einträge werden bei der Migration als Vermerk angelegt.</p><h2 id="schulformspezifische-anderungen" tabindex="-1">Schulformspezifische Änderungen <a class="header-anchor" href="#schulformspezifische-anderungen" aria-label="Permalink to &quot;Schulformspezifische Änderungen&quot;">​</a></h2><h3 id="grundschule" tabindex="-1">Grundschule <a class="header-anchor" href="#grundschule" aria-label="Permalink to &quot;Grundschule&quot;">​</a></h3><p>In der Grundschule fallen die Jahrgänge E1, E2 und E3 der Schuleingangsphase weg. Es werden nur noch die reinen Jahrgänge 01, 02, 03 und 04 erfasst.</p><p>Für Schülerinnen und Schüler in den Jahrgängen <strong>01 und 02</strong> wird zusätzlich das <strong>EP-Jahr E1, E2 oder E3</strong> in jedem Halbjahr unter <strong>Schüler ➜ Akt. Halbjahr ➜ Allgemeine Angaben</strong> zugeordnet. In <strong>Individualdaten I</strong> wird das momentane EP-Jahr aus der Schülertabelle zunächst nur angezeigt. Ab <strong>Jahrgang 03</strong> entfällt das Eingabefeld im Halbjahr; Korrekturen am gespeicherten Wert sind dann in <strong>Individualdaten I</strong> möglich. Siehe <a href="/schild3/schueler/eintragung-der-ep-jahre-tutorial.html">EP-Jahre eintragen</a>.</p><p>Beim Export nach ASDPC im Zuge der Statistik wird der Jahrgang automatisch korrekt auf die von ASDPC erwarteten Werte gesetzt.</p><h2 id="andere-module" tabindex="-1">Andere Module <a class="header-anchor" href="#andere-module" aria-label="Permalink to &quot;Andere Module&quot;">​</a></h2><h3 id="noteneingabe-im-svws-system" tabindex="-1">Noteneingabe im SVWS-System <a class="header-anchor" href="#noteneingabe-im-svws-system" aria-label="Permalink to &quot;Noteneingabe im SVWS-System&quot;">​</a></h3><p>Die Notenerfassung mit GradeHub und WeNoM ist dem SVWS-Server zugeordnet. Einrichtung und Bedienung sind in der <a href="https://doku.svws-nrw.de/" target="_blank" rel="noreferrer">SVWS-Dokumentation</a> beschrieben; siehe auch <a href="/zeugnisse/noteneingabe.html">Noten mit GradeHub und WeNoM erfassen</a>.</p><hr><p><a href="https://schulverwaltungsinfos.nrw.de/svws/wiki/index.php?title=Wesentliche_Unterschiede_zu_SchILD-NRW_2" target="_blank" rel="noreferrer">Originalartikel im Wiki</a> · Quellrevision 6944.</p>',34)])])}const v=a(c,[["render",g]]);export{w as __pageData,v as default};
